/**
 * TypeScript port of ml/inference/preprocessing.py (TOKENIZER v2). MUST stay equivalent —
 * verified by tests/unit/ml.test.ts against a fixture generated by ml/inference/predict.py.
 *
 * Preserves scam signals as typed tokens (urltoken + host words + tld_x, moneytoken, phonetoken,
 * pcttoken, numtoken, emailtoken) instead of deleting them; keeps Unicode letters + combining marks
 * (Devanagari words stay whole); emits word 1–2-grams and in-word char 3–5-grams.
 */

export const TOKENIZER_VERSION = "v2";

const INVISIBLE = /[​-‏‪-‮⁠-⁩﻿­]/g;
const URL_RE =
  /(?:https?:\/\/|www\.)[^\s<>"']+|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|in|net|org|xyz|top|info|io|co|ly|me|app|site|online|shop|live|icu|link|click|biz|cc|tk|ml|ga|cf|gq|buzz)(?:\/[^\s<>"']*)?/g;
const EMAIL = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/g;
const MONEY = /(?:₹|rs\.?|inr|\$|€|£|usd)\s?[0-9][0-9,]*(?:\.[0-9]+)?|[0-9][0-9,]*(?:\.[0-9]+)?\s?(?:rupees|rs|inr|lakhs?|crores?)\b/g;
const PHONE = /(?:\+?[0-9]{1,3}[\s-]?)?[0-9]{3,5}[\s-]?[0-9]{3,5}[\s-]?[0-9]{0,5}(?=[^0-9]|$)/g;
const PERCENT = /[0-9]+(?:\.[0-9]+)?\s?%/g;
const NUM = /[0-9]+/g;
const TOKEN = /[\p{L}\p{M}_]+/gu;
const SHORTENERS = new Set(["bit.ly", "tinyurl.com", "t.co", "goo.gl", "cutt.ly", "rb.gy", "is.gd", "ow.ly", "shorturl.at", "t.ly", "s.id", "tiny.cc"]);

function urlReplacement(raw: string): string {
  const host = raw.replace(/^(?:https?:\/\/)?(?:www\.)?/, "").split("/")[0].split("?")[0].split("#")[0].split(":")[0];
  const parts = host.split(/[.-]/).filter(Boolean);
  const tld = parts.length > 1 ? parts[parts.length - 1] : "";
  const words = tld ? parts.slice(0, -1).filter((p) => !/^[0-9]+$/.test(p)) : parts;
  const out = ["urltoken", ...words];
  if (tld) out.push(`tld_${tld}`);
  if (SHORTENERS.has(host)) out.push("shortlink");
  return ` ${out.join(" ")} `;
}

export function normalizeForModel(text: string): string {
  return text
    .normalize("NFKC")
    .replace(INVISIBLE, "")
    .toLowerCase()
    .replace(EMAIL, " emailtoken ")
    .replace(URL_RE, urlReplacement)
    .replace(MONEY, " moneytoken ")
    .replace(PERCENT, " pcttoken ")
    .replace(PHONE, (m) => ((m.match(/[0-9]/g)?.length ?? 0) >= 8 ? " phonetoken " : m))
    .replace(NUM, " numtoken ");
}

export function tokenize(text: string): string[] {
  return (normalizeForModel(text).match(TOKEN) ?? []).filter((t) => Array.from(t).length >= 2);
}

export function wordFeatures(text: string): string[] {
  const toks = tokenize(text);
  const out = [...toks];
  for (let i = 0; i + 1 < toks.length; i++) out.push(`${toks[i]} ${toks[i + 1]}`);
  return out;
}

export const CHAR_NGRAM_RANGE: [number, number] = [3, 5];

export function charFeatures(text: string): string[] {
  const out: string[] = [];
  const [lo, hi] = CHAR_NGRAM_RANGE;
  for (const tok of tokenize(text)) {
    const chars = Array.from(` ${tok} `); // code points, like Python
    for (let n = lo; n <= hi; n++) {
      if (chars.length < n) break;
      for (let i = 0; i + n <= chars.length; i++) out.push(chars.slice(i, i + n).join(""));
    }
  }
  return out;
}
